package com.unimend.motonav;

import android.app.*;
import android.appwidget.AppWidgetManager;
import android.os.*;
import android.graphics.Color;
import android.content.*;
import android.provider.Settings;
import android.text.InputType;
import android.Manifest;
import android.content.pm.PackageManager;
import android.location.*;
import android.view.*;
import android.widget.*;
import java.io.IOException;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

public class NavActivity extends Activity {
    private static final AtomicBoolean SCENE_LOADING=new AtomicBoolean(false);
    private int widgetId; private NavStore store; private ImageView preview; private TextView state; private Button sceneButton,routeButton,stopButton; private EditText keyInput,addressInput,lonInput,latInput; private double previewLat=Double.NaN,previewLon=Double.NaN,previewDataLat=Double.NaN,previewDataLon=Double.NaN; private org.json.JSONObject previewSceneData; private long lastPreviewRender; private GestureDetector mapGestures; private final ExecutorService io=Executors.newSingleThreadExecutor(); private final Handler handler=new Handler(Looper.getMainLooper());
    @Override public void onCreate(Bundle b){super.onCreate(b);widgetId=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,0);store=new NavStore(this);getWindow().setStatusBarColor(Color.BLACK);getWindow().setNavigationBarColor(Color.BLACK);
        LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(24),dp(22),dp(24),dp(28));body.setBackgroundColor(Color.BLACK);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(Color.BLACK);scroll.addView(body,new ScrollView.LayoutParams(-1,-2));setContentView(scroll);
        TextView title=text("OSM MAP · 3×3 地图原型",28,Color.WHITE);body.addView(title);preview=new ImageView(this);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);body.addView(preview,new LinearLayout.LayoutParams(-1,dp(360)));setupMapGestures();
        state=text("",16,Color.LTGRAY);state.setLineSpacing(dp(4),1);body.addView(state);
        sceneButton=new Button(this);sceneButton.setText("读取位置并刷新真实道路 / 建筑");body.addView(sceneButton);sceneButton.setOnClickListener(v->refreshScene());
        RouteStore routeStore=new RouteStore(this);keyInput=new EditText(this);keyInput.setHint("高德 Web 服务 Key");keyInput.setSingleLine(true);keyInput.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);keyInput.setText(routeStore.key());keyInput.setSelection(keyInput.length());keyInput.setTextColor(Color.WHITE);keyInput.setHintTextColor(Color.GRAY);body.addView(keyInput);
        addressInput=new EditText(this);addressInput.setHint("目的地地址 / 地点名称（例如：杭州东站）");addressInput.setSingleLine(true);addressInput.setText(routeStore.address());addressInput.setTextColor(Color.WHITE);addressInput.setHintTextColor(Color.GRAY);body.addView(addressInput);
        LinearLayout quick=new LinearLayout(this);quick.setOrientation(LinearLayout.HORIZONTAL);Button home=smallButton("回家"),work=smallButton("去公司"),recent=smallButton("最近");quick.addView(home,new LinearLayout.LayoutParams(0,dp(42),1));quick.addView(work,new LinearLayout.LayoutParams(0,dp(42),1));quick.addView(recent,new LinearLayout.LayoutParams(0,dp(42),1));body.addView(quick);home.setOnClickListener(v->useQuick(true));work.setOnClickListener(v->useQuick(false));home.setOnLongClickListener(v->{saveQuick(true);return true;});work.setOnLongClickListener(v->{saveQuick(false);return true;});recent.setOnClickListener(v->showRecent());
        LinearLayout destination=new LinearLayout(this);destination.setOrientation(LinearLayout.HORIZONTAL);lonInput=new EditText(this);lonInput.setHint("目的地经度 WGS84");lonInput.setText(routeStore.destLon());lonInput.setTextColor(Color.WHITE);latInput=new EditText(this);latInput.setHint("目的地纬度 WGS84");latInput.setText(routeStore.destLat());latInput.setTextColor(Color.WHITE);destination.addView(lonInput,new LinearLayout.LayoutParams(0,-2,1));destination.addView(latInput,new LinearLayout.LayoutParams(0,-2,1));body.addView(destination);
        LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);routeButton=new Button(this);routeButton.setText("规划并开始导航");stopButton=new Button(this);stopButton.setText("结束导航");stopButton.setVisibility(new NavSessionStore(this).active()?View.VISIBLE:View.GONE);actions.addView(routeButton,new LinearLayout.LayoutParams(0,-2,2));actions.addView(stopButton,new LinearLayout.LayoutParams(0,-2,1));body.addView(actions);routeButton.setOnClickListener(v->planRoute());stopButton.setOnClickListener(v->stopNavigation());
        TextView note=text("地图数据 © OpenStreetMap contributors。路线由高德路径规划 2.0 提供；Key 只保存在本应用私有存储。导航期间会持续更新位置、路线进度和下一转向距离；偏航确认后将限频重新规划。",14,Color.GRAY);body.addView(note);
        refresh(false);
    }
    private TextView text(String v,int size,int color){TextView t=new TextView(this);t.setText(v);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(8),0,dp(12));return t;}
    private Button smallButton(String label){Button b=new Button(this);b.setText(label);b.setTextSize(13);b.setAllCaps(false);return b;}
    private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
    private void refresh(boolean animate){int id=widgetId;SceneStore scene=new SceneStore(this);if(scene.ready()&&(Double.isNaN(previewLat)||Double.isNaN(previewLon))){previewLat=scene.lat();previewLon=scene.lon();previewDataLat=scene.lat();previewDataLon=scene.lon();}preview.setImageBitmap(previewSceneData!=null?NavRenderer.renderPreviewData(this,dp(360),dp(360),store,id,previewLat,previewLon,previewSceneData,scene.lat(),scene.lon()):(scene.ready()?NavRenderer.renderPreview(this,dp(360),dp(360),store,id,previewLat,previewLon):NavRenderer.render(this,dp(360),dp(360),store,id,-1)));lastPreviewRender=SystemClock.uptimeMillis();RouteStore route=new RouteStore(this);double moved=scene.ready()?distanceMeters(scene.lat(),scene.lon(),previewLat,previewLon):0;state.setText((widgetId>0?"当前组件 #"+widgetId:"应用预览")+(scene.ready()?"\n拖动地图浏览 · 双击回到当前位置":"\n尚未载入当前位置地图")+(moved>8?" · 偏移 "+Math.round(moved)+" m":"")+(route.ready()?" · 真实路线已缓存":""));}
    private void setupMapGestures(){mapGestures=new GestureDetector(this,new GestureDetector.SimpleOnGestureListener(){@Override public boolean onDown(MotionEvent e){return true;}@Override public boolean onScroll(MotionEvent a,MotionEvent b,float distanceX,float distanceY){SceneStore scene=new SceneStore(NavActivity.this);if(!scene.ready())return false;if(Double.isNaN(previewLat)){previewLat=scene.lat();previewLon=scene.lon();previewDataLat=scene.lat();previewDataLon=scene.lon();}double logicalX=distanceX*360.0/Math.max(1,preview.getHeight()),logicalY=distanceY*360.0/Math.max(1,preview.getHeight()),metersPerLogical=1040.0/340.0;previewLon+=logicalX*metersPerLogical/(111320.0*Math.cos(Math.toRadians(previewLat)));previewLat-=logicalY*metersPerLogical/111320.0;if(SystemClock.uptimeMillis()-lastPreviewRender>=48)refresh(false);return true;}@Override public boolean onDoubleTap(MotionEvent e){SceneStore scene=new SceneStore(NavActivity.this);if(scene.ready()){previewSceneData=null;previewLat=scene.lat();previewLon=scene.lon();previewDataLat=scene.lat();previewDataLon=scene.lon();refresh(false);}return true;}});preview.setOnTouchListener((v,e)->{boolean handled=mapGestures.onTouchEvent(e);if(e.getActionMasked()==MotionEvent.ACTION_UP){loadPreviewAtEdge();refresh(false);}else if(e.getActionMasked()==MotionEvent.ACTION_CANCEL)refresh(false);return handled;});}
    private void loadPreviewAtEdge(){if(Double.isNaN(previewDataLat)||distanceMeters(previewDataLat,previewDataLon,previewLat,previewLon)<520)return;final double lat=previewLat,lon=previewLon;state.setText("正在读取新中心的离线地图…");io.execute(()->{try{org.json.JSONObject data=OfflineSceneSource.fetch(this,lat,lon);if(data!=null)handler.post(()->{previewSceneData=data;previewDataLat=lat;previewDataLon=lon;refresh(false);});}catch(Exception e){android.util.Log.w("MotoNav","preview edge scene",e);}});}
    private double distanceMeters(double aLat,double aLon,double bLat,double bLon){if(Double.isNaN(bLat)||Double.isNaN(bLon))return 0;double y=(bLat-aLat)*111320.0,x=(bLon-aLon)*111320.0*Math.cos(Math.toRadians(aLat));return Math.hypot(x,y);}
    @Override protected void onResume(){super.onResume();if(store!=null)refresh(false);}
    private void refreshScene(){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},41);return;}LocationManager lm=(LocationManager)getSystemService(LOCATION_SERVICE);Location best=null;for(String provider:lm.getProviders(true)){Location x=lm.getLastKnownLocation(provider);if(x!=null&&(best==null||x.getTime()>best.getTime()))best=x;}if(best!=null){fetchScene(best);return;}sceneButton.setEnabled(false);sceneButton.setText("正在获取位置…");LocationListener listener=new LocationListener(){public void onLocationChanged(Location l){lm.removeUpdates(this);fetchScene(l);}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}public void onStatusChanged(String p,int s,Bundle b){}};try{lm.requestLocationUpdates(LocationManager.GPS_PROVIDER,0,0,listener);}catch(Exception e){sceneButton.setEnabled(true);sceneButton.setText("无法获取位置，请开启定位");}}
    private void fetchScene(Location l){if(!SCENE_LOADING.compareAndSet(false,true)){sceneButton.setText("场景正在载入，请稍候…");return;}sceneButton.setEnabled(false);sceneButton.setText("优先读取杭州离线地图…");final double lat=l.getLatitude(),lon=l.getLongitude();io.execute(()->{try{org.json.JSONObject data=SceneSource.fetch(this,lat,lon);new SceneStore(this).save(data,lat,lon);handler.post(()->{previewSceneData=null;previewLat=lat;previewLon=lon;previewDataLat=lat;previewDataLon=lon;sceneButton.setEnabled(true);sceneButton.setText((data.optBoolean("offline")?"离线地图 · ":"在线地图 · ")+data.optInt("buildings")+" 个建筑 / "+data.optInt("roads")+" 条道路");NavWidget.publish(this);refresh(false);});}catch(Exception e){android.util.Log.w("MotoNav","OSM scene",e);handler.post(()->{sceneButton.setEnabled(true);sceneButton.setText("载入失败：本地无覆盖且网络无响应");});}finally{SCENE_LOADING.set(false);}});}
    private void planRoute(){
        if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},41);return;}
        String key=keyInput.getText().toString().trim(),address=addressInput.getText().toString().trim(),lonText=lonInput.getText().toString(),latText=latInput.getText().toString();
        if(!key.matches("[0-9a-fA-F]{32}")){routeButton.setText("请检查 32 位高德 Web 服务 Key");return;}
        Location origin=bestLocation();SceneStore scene=new SceneStore(this);final double originLat=origin!=null?origin.getLatitude():scene.lat(),originLon=origin!=null?origin.getLongitude():scene.lon();
        if(Double.isNaN(originLat)||Double.isNaN(originLon)){routeButton.setText("请先刷新当前位置地图");return;}
        RouteStore routeStore=new RouteStore(this);routeStore.begin(key,address);NavWidget.publish(this);routeButton.setEnabled(false);
        if(address.length()==0){try{planResolved(key,address,new AmapGeocoder.Result(Double.parseDouble(latText),Double.parseDouble(lonText),"坐标目的地"),originLat,originLon);}catch(Exception e){routeFailure(new IOException("目的地经纬度格式错误"));}return;}
        routeButton.setText("正在搜索候选地点…");
        io.execute(()->{try{AmapGeocoder.Result[] results=AmapGeocoder.search(key,address,originLat,originLon);handler.post(()->showCandidates(key,address,results,originLat,originLon));}catch(Exception e){routeFailure(e);}});
    }
    private void showCandidates(String key,String address,AmapGeocoder.Result[] results,double originLat,double originLon){
        if(isFinishing())return;if(results.length==1){planResolved(key,address,results[0],originLat,originLon);return;}String[] labels=new String[results.length];for(int i=0;i<results.length;i++)labels[i]=results[i].name+(results[i].distance>=0?"\n距离约 "+results[i].distance+" m":"");routeButton.setText("请选择正确的目的地");new AlertDialog.Builder(this).setTitle("附近的目的地").setItems(labels,(d,which)->planResolved(key,address,results[which],originLat,originLon)).setOnCancelListener(d->{routeButton.setEnabled(true);routeButton.setText("已取消，请重新规划");}).show();
    }
    private void planResolved(String key,String address,AmapGeocoder.Result result,double originLat,double originLon){
        routeButton.setEnabled(false);routeButton.setText("正在请求高德路径规划 2.0…");io.execute(()->{try{String finalLon=String.format(java.util.Locale.US,"%.6f",result.lon),finalLat=String.format(java.util.Locale.US,"%.6f",result.lat);RouteStore routeStore=new RouteStore(this);routeStore.config(key,address,finalLon,finalLat);org.json.JSONObject route=AmapRouteSource.fetch(key,originLat,originLon,result.lat,result.lon);route.put("destination",result.name);routeStore.save(route);routeStore.remember(address,result.name,finalLon,finalLat);handler.post(()->{lonInput.setText(finalLon);latInput.setText(finalLat);routeButton.setEnabled(true);routeButton.setText("导航中 · "+route.optInt("distance")+" m");startNavigation();NavWidget.publish(this);refresh(false);});}catch(Exception e){routeFailure(e);}});
    }
    private void startNavigation(){Intent i=new Intent(this,NavForegroundService.class).setAction(NavForegroundService.START);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);stopButton.setVisibility(View.VISIBLE);}
    private void stopNavigation(){startService(new Intent(this,NavForegroundService.class).setAction(NavForegroundService.STOP));stopButton.setVisibility(View.GONE);routeButton.setText("规划并开始导航");handler.postDelayed(()->refresh(false),250);}
    private void saveQuick(boolean isHome){String value=addressInput.getText().toString().trim();if(value.length()==0){routeButton.setText("请先输入地址，再长按保存");return;}RouteStore rs=new RouteStore(this);if(isHome)rs.home(value);else rs.work(value);routeButton.setText("已保存为"+(isHome?"家":"公司"));}
    private void useQuick(boolean isHome){RouteStore rs=new RouteStore(this);String value=isHome?rs.home():rs.work();if(value.length()==0){routeButton.setText("长按“"+(isHome?"回家":"去公司")+"”可保存当前输入");return;}addressInput.setText(value);planRoute();}
    private void showRecent(){org.json.JSONArray list=new RouteStore(this).recent();if(list.length()==0){routeButton.setText("还没有最近目的地");return;}String[] labels=new String[list.length()];for(int i=0;i<labels.length;i++){org.json.JSONObject item=list.optJSONObject(i);labels[i]=item==null?"":item.optString("name",item.optString("query"));}new AlertDialog.Builder(this).setTitle("最近目的地").setItems(labels,(d,which)->{org.json.JSONObject item=list.optJSONObject(which);if(item!=null){addressInput.setText(item.optString("query"));lonInput.setText(item.optString("lon"));latInput.setText(item.optString("lat"));planRoute();}}).show();}
    private void routeFailure(Exception e){android.util.Log.w("MotoNav","AMap route",e);handler.post(()->{routeButton.setEnabled(true);routeButton.setText("路线失败："+e.getMessage());NavWidget.publish(this);refresh(false);});}
    private Location bestLocation(){LocationManager lm=(LocationManager)getSystemService(LOCATION_SERVICE);Location best=null;try{for(String provider:lm.getProviders(true)){Location x=lm.getLastKnownLocation(provider);if(x!=null&&(best==null||x.getTime()>best.getTime()))best=x;}}catch(SecurityException ignored){}return best;}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==41&&results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)refreshScene();else if(request==41)sceneButton.setText("需要精确位置才能载入真实建筑");}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);io.shutdownNow();super.onDestroy();}
}

